<?php
$managerUrl=static fn(array $changes=[])=>$url(array_replace(['view'=>$view,'id'=>$plan['id']??0,'month'=>$month->format('Y-m'),'planner_layout'=>$plannerLayout,'scale'=>$plannerScale,'day'=>$plannerDate,'holidays'=>$campaignFilters['holidays'],'plan_search'=>$planSearch??'','plan_sort'=>$planSort??'updated_at','plan_direction'=>$planDirection??'desc'],$changes));
$planValues=($campaignRecovery['action']??'')==='campaign_plan_save'?$campaignRecovery:($plan?['name'=>$plan['name']]+$plan['data']:[]);
$touchpointValues=($campaignRecovery['action']??'')==='campaign_touchpoint_save'?$campaignRecovery:[];
if(($campaignRecovery['action']??'')==='campaign_plan_save')$planValues['tracking']=audienceCampaignTracking($campaignRecovery);
$planState=static function(array $data):string{$today=(new DateTimeImmutable('now',new DateTimeZone('America/Chicago')))->format('Y-m-d');return $today<($data['start']??'')?'Ready':($today>($data['end']??'')?'Concluded':'Active');};
$planForm=static function(string $action,array $values=[])use($csrf){echo $csrf;audienceInputs(['action'=>$action]+$values);};
?>
<nav class="campaign-tabs" aria-label="Campaign Manager views"><?php foreach(['calendar'=>'Calendar','agenda'=>'Agenda','list'=>'Campaigns list']as$key=>$label): ?><a href="<?= $h($managerUrl(['planner_layout'=>$key])) ?>"<?= $plannerLayout===$key?' aria-current="page"':'' ?>><?= $label ?></a><?php endforeach; ?></nav>
<?php if($plan): ?><div class="campaign-plan-overview"><a href="<?= $h($url(['view'=>'campaign-manager'])) ?>">← All campaigns</a><span class="campaign-status"><?= $planState($plan['data']) ?></span><h2><?= $h($plan['data']['goal']) ?></h2><p><?= $h($plan['data']['start']) ?> – <?= $h($plan['data']['end']) ?></p><p><?= nl2br($h($plan['data']['notes']??'')) ?></p><?php if($canManage): ?><form method="post" data-confirm="Delete this campaign plan? Its emails, tasks and events will be kept as unassociated touchpoints."><?php $planForm('campaign_plan_operation',['id'=>$plan['id'],'version'=>$plan['version']]); ?><button name="operation" value="replicate" data-skip-plan-confirm>Replicate campaign</button><button name="operation" value="delete">Delete campaign</button></form><?php endif; ?></div><?php endif; ?>
<?php if($plannerLayout==='list'): ?>
<form method="get" class="campaign-plan-search"><?php audienceInputs(['view'=>'campaign-manager','planner_layout'=>'list']); ?><label>Search campaigns<input type="search" name="plan_search" value="<?= $h($planSearch??'') ?>" placeholder="Search campaigns"></label><label>Sort by<select name="plan_sort"><option value="updated_at"<?= ($planSort??'updated_at')==='updated_at'?' selected':'' ?>>Date edited</option><option value="name"<?= ($planSort??'')==='name'?' selected':'' ?>>Name</option></select></label><label>Order<select name="plan_direction"><option value="desc"<?= ($planDirection??'desc')==='desc'?' selected':'' ?>>Descending</option><option value="asc"<?= ($planDirection??'')==='asc'?' selected':'' ?>>Ascending</option></select></label><button>Search</button></form>
<div class="audience-table-card audience-table-scroll"><table class="data-table audience-table"><thead><tr><th>Name</th><th>Goal</th><th>Dates</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($planRows as$item):$data=audienceJson($item['data_json']); ?><tr><td><a href="<?= $h($url(['view'=>'campaign-plan','id'=>$item['id']])) ?>"><?= $h($item['name']) ?></a></td><td><?= $h($data['goal']) ?></td><td><?= $h($data['start']) ?> – <?= $h($data['end']) ?></td><td><?= $planState($data) ?></td><td><a class="audience-button" href="<?= $h($url(['view'=>'campaign-plan','id'=>$item['id']])) ?>">Manage campaign</a></td></tr><?php endforeach; ?><?php if(!$planRows): ?><tr><td colspan="5" class="audience-empty">No campaign plans yet.</td></tr><?php endif; ?></tbody></table></div>
<div class="campaign-pagination"><span><?= number_format($planTotal??count($planRows)) ?> campaigns</span><div><?php $planPages=max(1,(int)ceil(($planTotal??count($planRows))/25));if(($planPage??1)>1): ?><a class="audience-button" href="<?= $h($managerUrl(['plan_page'=>$planPage-1])) ?>">Previous</a><?php endif; ?><span>Page <?= $planPage??1 ?> of <?= $planPages ?></span><?php if(($planPage??1)<$planPages): ?><a class="audience-button" href="<?= $h($managerUrl(['plan_page'=>($planPage??1)+1])) ?>">Next</a><?php endif; ?></div></div>
<?php else: ?>
<form method="get" class="campaign-planner-filters"><?php audienceInputs(['view'=>$view,'id'=>$plan['id']??0,'month'=>$month->format('Y-m'),'planner_layout'=>$plannerLayout,'day'=>$plannerDate]); ?><label>Holidays<select name="holidays" data-auto-submit><option value="0">None</option><option value="1"<?= $campaignFilters['holidays']==='1'?' selected':'' ?>>United States</option></select></label><label>View<select name="scale" data-auto-submit><?php foreach(['month'=>'Month','week'=>'Week','day'=>'Day']as$key=>$label): ?><option value="<?= $key ?>"<?= $plannerScale===$key?' selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><span>Planning dates and times: UTC</span></form>
<?php $focus=new DateTimeImmutable($plannerDate,new DateTimeZone('UTC'));[$start,$end]=audienceCampaignPlannerRange($plannerDate,$plannerScale);$step=$plannerScale==='month'?'month':($plannerScale==='week'?'week':'day');$holidays=$campaignFilters['holidays']==='1'?audienceCampaignHolidays((int)$start->format('Y'))+audienceCampaignHolidays((int)$end->format('Y')):[]; ?>
<div class="campaign-calendar-heading"><h2><?= $plannerScale==='month'?$month->format('F Y'):$start->format('M j, Y').($start!=$end?' – '.$end->format('M j, Y'):'') ?></h2><a class="audience-button" href="<?= $h($managerUrl(['month'=>gmdate('Y-m'),'day'=>gmdate('Y-m-d')])) ?>">Today</a><?php foreach(['-1'=>'Previous','+1'=>'Next']as$offset=>$label):$next=($plannerScale==='month'?$month:$focus)->modify($offset.' '.$step); ?><a class="audience-button" aria-label="<?= $label ?> <?= $step ?>" href="<?= $h($managerUrl(['month'=>$next->format('Y-m'),'day'=>$next->format('Y-m-d')])) ?>"><?= $offset==='-1'?'‹':'›' ?></a><?php endforeach; ?></div>
<?php if(count($touchpoints)>1000): ?><p class="audience-notice">More than 1,000 touchpoints match this period. Narrow the period to see additional items.</p><?php endif; ?>
<?php if($plannerLayout==='agenda'): ?><div class="campaign-agenda"><?php foreach(array_slice($touchpoints,0,1000)as$item):$data=audienceJson($item['data_json']); ?><article><time><?= $h(substr($item['start_at'],0,16)) ?> – <?= $h(substr($item['end_at'],0,16)) ?></time><div><span class="campaign-status"><?= $h(ucfirst($item['touchpoint_type'])) ?></span><h3><?= $h($item['name']) ?></h3><p><?= $h($data['notes']??'') ?></p><small><?= $h($item['touchpoint_type']==='email'?($item['email_status']??'Unavailable'):str_replace('-',' ',ucfirst($item['state']))) ?></small></div><?php if($canManage): ?><button type="button" data-touchpoint-edit='<?= $h(json_encode($item,JSON_THROW_ON_ERROR)) ?>'>Edit</button><?php endif; ?><?php if($item['campaign_id']&&!$item['email_deleted']): ?><a href="<?= $h($url(['view'=>'campaign','id'=>$item['campaign_id']])) ?>">View email</a><?php endif; ?></article><?php endforeach; ?><?php if(!$touchpoints): ?><p class="audience-empty">No touchpoints in this period.</p><?php endif; ?></div>
<?php else: ?><div class="campaign-calendar-scroll"><table class="data-table campaign-calendar<?= $plannerScale==='day'?' campaign-calendar-day':'' ?>" aria-label="Campaign Manager calendar"><thead><tr><?php foreach($plannerScale==='day'?[$start->format('D')]:['Mon','Tue','Wed','Thu','Fri','Sat','Sun']as$day): ?><th><?= $day ?></th><?php endforeach; ?></tr></thead><tbody><?php for($day=$start;$day<=$end;$day=$day->modify('+1 day')): ?><?= $day===$start||$day->format('N')==='1'?'<tr>':'' ?><td><time><?= $day->format('j') ?></time><?php if(isset($holidays[$day->format('Y-m-d')])): ?><small class="campaign-holiday"><?= $h($holidays[$day->format('Y-m-d')]) ?></small><?php endif; ?><?php foreach(array_slice($touchpoints,0,1000)as$item)if(substr($item['start_at'],0,10)<=$day->format('Y-m-d')&&substr($item['end_at'],0,10)>=$day->format('Y-m-d')): ?><button type="button" class="campaign-touchpoint-chip" data-touchpoint-edit='<?= $h(json_encode($item,JSON_THROW_ON_ERROR)) ?>'<?= !$canManage?' disabled':'' ?> title="<?= $h($item['name'].' · '.$item['touchpoint_type'].' · '.$item['state']) ?>"><?= $h($item['name']) ?><small><?= $h(ucfirst($item['touchpoint_type'])) ?></small></button><?php endif; ?><?php if($canManage): ?><button class="campaign-day-add" type="button" data-touchpoint-new="<?= $day->format('Y-m-d') ?>" aria-label="Add touchpoint on <?= $day->format('M j') ?>">+</button><?php endif; ?></td><?= $day===$end||$day->format('N')==='7'?'</tr>':'' ?><?php endfor; ?></tbody></table></div><?php endif; ?>
<?php if($plan): ?><section class="campaign-todo"><h2>To do</h2><?php $todoCount=0;foreach($touchpoints as$item)if(($item['touchpoint_type']==='task'&&$item['state']!=='complete')||($item['touchpoint_type']==='email'&&$item['email_status']==='draft')):$todoCount++; ?><div><strong><?= $h($item['name']) ?></strong><time><?= $h(substr($item['end_at'],0,10)) ?></time><?php if($canManage): ?><button type="button" data-touchpoint-edit='<?= $h(json_encode($item,JSON_THROW_ON_ERROR)) ?>'>Edit</button><?php endif; ?></div><?php endif; ?><?php if(!$todoCount): ?><p>No incomplete tasks or draft email touchpoints in this period.</p><?php endif; ?></section><?php endif; ?>
<?php endif; ?>
<?php if($canManage): ?>
<dialog id="campaign-plan-editor" class="campaign-plan-editor" aria-labelledby="campaign-plan-editor-title"<?= ($campaignRecovery['action']??'')==='campaign_plan_save'?' data-reopen-dialog':'' ?>><header><h2 id="campaign-plan-editor-title">Campaign settings</h2><button data-close-dialog aria-label="Close campaign settings">×</button></header><?php if(($campaignRecovery['action']??'')==='campaign_plan_save'): ?><p class="audience-notice error" role="alert"><?= $h($error) ?></p><?php endif; ?><form method="post"><?php $planForm('campaign_plan_save',['id'=>($campaignRecovery['action']??'')==='campaign_plan_save'?($campaignRecovery['id']??0):($plan['id']??0),'version'=>$campaignRecovery['version']??$plan['version']??0]); ?><label>Campaign name<input name="name" maxlength="100" required value="<?= $h($planValues['name']??'') ?>"></label><label>Marketing goal<select name="goal"><?php foreach(audienceCampaignGoals()as$goal): ?><option<?= ($planValues['goal']??'')===$goal?' selected':'' ?>><?= $goal ?></option><?php endforeach; ?></select></label><div class="form-grid"><label>Start date<input type="date" name="start" required value="<?= $h($planValues['start']??gmdate('Y-m-d')) ?>"></label><label>End date<input type="date" name="end" required value="<?= $h($planValues['end']??gmdate('Y-m-d',time()+30*86400)) ?>"></label></div><label>Notes<textarea name="notes" maxlength="4000"><?= $h($planValues['notes']??'') ?></textarea></label><h3>Set email tracking settings</h3><?php foreach(['opens'=>'Track opens','clicks'=>'Track clicks','plain_clicks'=>'Track plain-text clicks','inbox'=>'Use Inbox to manage replies','video'=>'Auto-convert video']as$key=>$label): ?><label class="audience-check"><input type="checkbox" name="<?= $key ?>" value="1"<?= !empty($planValues['tracking'][$key])?' checked':'' ?>><?= $label ?></label><?php endforeach; ?><div class="dialog-actions"><button type="button" data-close-dialog>Cancel</button><button class="primary"><?= $plan?'Save':'Create campaign' ?></button></div></form></dialog>
<dialog id="campaign-touchpoint-editor" aria-labelledby="campaign-touchpoint-title"<?= ($campaignRecovery['action']??'')==='campaign_touchpoint_save'?' data-reopen-dialog':'' ?>><header><h2 id="campaign-touchpoint-title">Add touchpoint</h2><button data-close-dialog aria-label="Close touchpoint">×</button></header><?php if($touchpointValues): ?><p class="audience-notice error" role="alert"><?= $h($error) ?></p><?php endif; ?><form method="post" data-touchpoint-form><?php $planForm('campaign_touchpoint_save',['id'=>$touchpointValues['id']??0,'version'=>$touchpointValues['version']??0]); ?><label>Associate with a campaign<select name="plan_id"><option value="0">Do not associate with a campaign</option><?php foreach(($planChoices??$planRows)as$item): ?><option value="<?= $item['id'] ?>"<?= (int)($touchpointValues['plan_id']??$plan['id']??0)===(int)$item['id']?' selected':'' ?>><?= $h($item['name']) ?></option><?php endforeach; ?></select></label><label>Touchpoint type<select name="touchpoint_type"><?php foreach(['task'=>'Task','event'=>'Event','email'=>'Email']as$key=>$label): ?><option value="<?= $key ?>"<?= ($touchpointValues['touchpoint_type']??'task')===$key?' selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Name<input name="name" maxlength="100" required value="<?= $h($touchpointValues['name']??'') ?>"></label><div class="form-grid"><label>Start date and time (UTC)<input type="datetime-local" name="start_at" required value="<?= $h($touchpointValues['start_at']??'') ?>"></label><label>End date and time (UTC)<input type="datetime-local" name="end_at" required value="<?= $h($touchpointValues['end_at']??'') ?>"></label></div><label>Status<select name="state"><?php foreach(['not-started'=>'Not started','in-progress'=>'In progress','complete'=>'Complete']as$key=>$label): ?><option value="<?= $key ?>"<?= ($touchpointValues['state']??'not-started')===$key?' selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Event type<input name="event_type" maxlength="80" value="<?= $h($touchpointValues['event_type']??'') ?>" placeholder="Webinar, sale, launch..."></label><label>Email<select name="campaign_id"><option value="0">Choose an email</option><?php foreach($plannerEmails as$email): ?><option value="<?= $email['id'] ?>"<?= (int)($touchpointValues['campaign_id']??0)===(int)$email['id']?' selected':'' ?>><?= $h($email['name']) ?></option><?php endforeach; ?></select></label><a href="<?= $h($url(['view'=>'campaigns','create'=>1])) ?>">Create an email</a><label class="audience-check" data-touchpoint-tracking><input type="checkbox" name="use_plan_tracking" value="1"<?= ($touchpointValues['use_plan_tracking']??'')==='1'?' checked':'' ?>>Apply the associated campaign’s tracking preferences to this email draft</label><label>Notes<textarea name="notes" maxlength="4000"><?= $h($touchpointValues['notes']??'') ?></textarea></label><div class="dialog-actions"><button type="button" data-close-dialog>Cancel</button><button class="primary">Save</button></div></form><form method="post" data-touchpoint-actions data-confirm="Delete this touchpoint? Its email, if any, will be kept." hidden><?php $planForm('campaign_touchpoint_operation',['id'=>0,'version'=>0,'plan_id'=>$plan['id']??0]); ?><button name="operation" value="replicate" data-skip-plan-confirm>Replicate</button><button name="operation" value="delete" data-touchpoint-delete>Delete</button></form></dialog>
<?php endif; ?>
